import{z as n,x as s,o as l,c as p,q as t,j as r,D as e,d as a,s as o,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"多模态投机解码","description":"","frontmatter":{"title":"多模态投机解码","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-multimodal-speculative.md","filePath":"llm/mm-multimodal-speculative.md","lastUpdated":1791063341000}'),m={name:"llm/mm-multimodal-speculative.md"};function d(C,E,h,D,F,u){const B=s("Mermaid");return l(),p("div",null,[E[2]||(E[2]=t('<h1 id="多模态投机解码" tabindex="-1">多模态投机解码 <a class="header-anchor" href="#多模态投机解码" aria-label="Permalink to &quot;多模态投机解码&quot;">​</a></h1><div class="epigraph"><p>投机解码赚的是接受率的钱；图一进来，同一段输出里有的 token 唾手可得，有的一个都猜不中。</p><footer>—— 据 Leviathan et al. 与 Chen et al., 2023（投机解码）；Li et al., EAGLE, 2024；Cai et al., Medusa, 2024 整理</footer></div><p><a href="/llm/mm-multimodal-kv">上一课</a>把视觉 KV 的缓存与驱逐管好；本课回到解码加速。投机解码的拒绝-接受采样与期望收益由<a href="/llm/speculative-decoding">投机解码</a>给出，草稿谱系见 <a href="/llm/eagle">EAGLE</a> 与 <a href="/llm/medusa">Medusa</a>，整线的批交互收在<a href="/llm/spec-map">投机收束</a>。多模态不改算法，改的是<strong>接受率的分布</strong>：视觉前缀让某些输出段近乎可抄、某些段几乎不可猜，投机的开关要从「全局开」变成「按内容开」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接受率 \\(\\alpha\\) 的定义不变：草稿 token 被目标接受的概率。多模态把它按内容劈开。视觉描述类输出高度模板化——「图中左侧有一座……」的结构与词汇都可预测，\\(\\alpha\\) 高；OCR、表格数字、代码、URL 类输出，每个 token 是从图里读出的独立事实，草稿不看图就猜不中，\\(\\alpha\\) 低到接近乱猜。平均值失去意义：一条图文请求里两段输出交替，整体 \\(\\alpha\\) 是混合数，而收益随 \\(\\alpha\\) 指数变化，混合数同时高估简单段、低估困难段。</p><p><span class="marginnote">投机解码可以类比「写作文先让快手助手打草稿、老师逐段批改」：助手猜得准，老师一次过一整段，省时间；猜不准就整段作废重来。草稿模型小而快、目标模型大而准，最终以老师的批改为准，所以正确性不受损，赚的只是速度。</span></p><p>草稿侧还有一个结构缺口：文本草稿模型根本看不见图。它对「下一个描述哪个物体」完全无知，猜中全靠语言惯性。把视觉信息喂给草稿成为多模态投机特有的设计点——喂多少、用什么形式、草稿模型要不要重新训练，各有代价。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条部署路线，按草稿获得视觉信息的多少排。<strong>纯文本草稿</strong>：草稿只读已生成文本，实现最简，但图强相关段接受率塌方，只适合叙述为主的负载。<strong>视觉摘要草稿</strong>：把视觉嵌入池化成几百 token 喂给草稿（不跑完整编码器），困难段接受率回升，代价是草稿前向变贵且要蒸馏适配。<strong>自草稿头</strong>：<a href="/llm/eagle">EAGLE</a> 与 <a href="/llm/medusa">Medusa</a> 一类复用目标模型内部特征出草稿，视觉 token 的特征天然在特征流里，「看图」不需要额外通道——多模态目标配自草稿头，是当前性价比最高的组合。</p><p>按内容路由的开关补最后一层：输出进入 OCR 串、数字、代码等高信息密度区时临时关投机（信号是正则或 token 类型），回到叙述段再开。开关本身要便宜，否则省下的验证钱又花回路由上。</p><p><span class="marginnote">期望接受块长为 \\(\\frac{1-\\alpha^{k+1}}{1-\\alpha}\\)：\\(\\alpha=0.7\\)、草稿深度 \\(k=4\\) 时约 \\(2.4\\)；OCR 段 \\(\\alpha\\) 掉到 \\(0.3\\)，同一公式只剩约 \\(1.15\\)，草稿前向的钱白烧。按段开关不是优化，是保本。</span></p>',11)),(l(),r(i,null,{default:e(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%9B%BE%E5%83%8F%E7%BC%96%E7%A0%81%E8%BF%9B%E5%89%8D%E7%BC%80%22%5D%20--%3E%20TGT%5B%22%E7%9B%AE%E6%A0%87%20VLM%20prefill%22%5D%0A%20%20TGT%20--%3E%20DRAFT%7B%22%E8%8D%89%E7%A8%BF%E8%B7%AF%E7%BA%BF%22%7D%0A%20%20DRAFT%20--%3E%7C%E7%BA%AF%E6%96%87%E6%9C%AC%7C%20T1%5B%22%E5%B0%8F%20LLM%20%E5%8F%AA%E8%AF%BB%E5%B7%B2%E7%94%9F%E6%88%90%E6%96%87%E6%9C%AC%22%5D%0A%20%20DRAFT%20--%3E%7C%E8%A7%86%E8%A7%89%E6%91%98%E8%A6%81%7C%20T2%5B%22%E6%B1%A0%E5%8C%96%E5%B5%8C%E5%85%A5%E5%96%82%E8%8D%89%E7%A8%BF%22%5D%0A%20%20DRAFT%20--%3E%7C%E8%87%AA%E8%8D%89%E7%A8%BF%E5%A4%B4%7C%20T3%5B%22%E5%A4%8D%E7%94%A8%E7%9B%AE%E6%A0%87%E6%A8%A1%E5%9E%8B%E7%89%B9%E5%BE%81%22%5D%0A%20%20T1%20--%3E%20K%5B%22%E5%87%BA%20k%20%E4%B8%AA%E8%8D%89%E7%A8%BF%20token%22%5D%0A%20%20T2%20--%3E%20K%0A%20%20T3%20--%3E%20K%0A%20%20K%20--%3E%20VER%7B%22%E7%9B%AE%E6%A0%87%E5%B9%B6%E8%A1%8C%E9%AA%8C%E8%AF%81%22%7D%0A%20%20VER%20--%3E%7C%E6%8E%A5%E5%8F%97%7C%20ACC%5B%22%E6%95%B4%E5%9D%97%E6%8F%90%E4%BA%A4%22%5D%0A%20%20VER%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20ROLL%5B%22%E5%9B%9E%E6%BB%9A%E5%88%B0%E6%9C%80%E5%90%8E%E6%8E%A5%E5%8F%97%E5%A4%84%22%5D%0A%20%20ACC%20--%3E%20ROUTE%5B%22%E6%8C%89%E5%86%85%E5%AE%B9%E7%B1%BB%E5%9E%8B%E5%AE%9A%E4%B8%8B%E8%BD%AE%E5%BC%80%E5%85%B3%22%5D%0A%20%20ROLL%20--%3E%20ROUTE%0A%20%20ROUTE%20--%3E%20K%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("拒绝-接受采样的正确性只依赖一个条件：草稿与目标在"),A("strong",null,"同一条件分布"),a("上比较，修改规则保证输出仍服从目标分布。多模态的陷阱在「条件」二字：草稿若看的是与目标不同的视觉表示（不同分辨率、不同编码器），它逼近的就不是目标的条件分布——采样修正仍保正确，接受率却被表示差吃掉。这是「草稿的视觉通道必须与目标同源」的原理依据，也是自草稿头天然占优的原因：特征同一份，不存在表示差。")],-1)),(l(),r(i,null,{default:e(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%8D%89%E7%A8%BF%E7%9A%84%E8%A7%86%E8%A7%89%E8%A1%A8%E7%A4%BA%E4%B8%8E%E7%9B%AE%E6%A0%87%E5%90%8C%E6%BA%90%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E8%87%AA%E8%8D%89%E7%A8%BF%E5%A4%B4%22%7C%20SAME%5B%22%E6%AF%94%E8%BE%83%E5%8F%91%E7%94%9F%E5%9C%A8%E5%90%8C%E4%B8%80%E6%9D%A1%E4%BB%B6%E5%88%86%E5%B8%83%E4%B8%8A%22%5D%0A%20%20SAME%20--%3E%20OK%5B%22%E4%BF%AE%E6%AD%A3%E8%A7%84%E5%88%99%E4%BF%9D%E6%AD%A3%E7%A1%AE%EF%BC%8C%E6%8E%A5%E5%8F%97%E7%8E%87%E8%B6%B3%E9%A2%9D%E5%85%91%E7%8E%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E4%B8%8D%E5%90%8C%E5%88%86%E8%BE%A8%E7%8E%87%E6%88%96%E7%BC%96%E7%A0%81%E5%99%A8%22%7C%20DIFF%5B%22%E8%8D%89%E7%A8%BF%E9%80%BC%E8%BF%91%E7%9A%84%E6%98%AF%E5%8F%A6%E4%B8%80%E4%B8%AA%E6%9D%A1%E4%BB%B6%E5%88%86%E5%B8%83%22%5D%0A%20%20DIFF%20--%3E%20FIX%5B%22%E6%8B%92%E7%BB%9D-%E6%8E%A5%E5%8F%97%E9%87%87%E6%A0%B7%E4%BB%8D%E4%BF%9D%E8%BE%93%E5%87%BA%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20FIX%20--%3E%20LOSS%5B%22%E4%BD%86%E6%8E%A5%E5%8F%97%E7%8E%87%E8%A2%AB%E8%A1%A8%E7%A4%BA%E5%B7%AE%E5%90%83%E6%8E%89%EF%BC%8C%E5%8A%A0%E9%80%9F%E7%BC%A9%E6%B0%B4%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p>语音是反例课。语音 token 二分（<a href="/llm/speech-tokenizer">语音 tokenizer</a>）：语义类单元随词内容走，可预测、可投机；声学码本深层下标接近均匀分布，\\(\\alpha\\) 趋近随机水平，投机只亏不赚。TTS 的声学合成不开投机，ASR 的文本输出照常开——同一条语音管线里，投机按 token 类型分段适用。视频帧流的增量 prefill 与投机正交：一个省编码与 prefill，一个省解码，可叠加但账分开记。</p><p><span class="marginnote">常见误区：只看平均接受率。一段 \\(\\alpha=0.9\\) 的叙述配一段 \\(\\alpha=0.2\\) 的 OCR，平均 0.55 看着「还凑合」，但收益随 \\(\\alpha\\) 指数变化——分开统计才会发现 OCR 段每一步草稿都在亏钱。这就是评测必须按内容分桶的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>批处理是投机收益的隐形天花板：大批下验证前向早已算满，草稿省不下墙钟时间，收益随批大小递减；图文负载的视觉 prefill 又抬高批压力——多模态在线服务里投机常只在低峰或小批会话开。<span class="marginnote">为什么大批下投机失灵？投机赚的是「验证 k 个 token 不比验证 1 个贵多少」的并行余量；大批时 GPU 的并行额度早被真实请求占满，草稿 token 只能排队插空，省不下墙钟时间。低峰期并行额度空闲，才是投机的窗口。</span>接受率评测必须按内容分桶，平均 \\(\\alpha\\) 会在模型升级时给反向信号：叙述段变模板化拉高平均，困难段其实没变。路由误判代价不对称：OCR 段误开只亏性能，叙述段误关只亏加速；但频繁开关让 TTFT 抖动，尾延迟敏感的会话宁可用保守固定档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模态不改投机算法，改接受率分布：描述段高、OCR 数字段低，平均值失去意义。</li><li>草稿获得视觉信息的三档路线：纯文本、视觉摘要、自草稿头；末者表示同源、性价比最高。</li><li>按内容路由开关投机，OCR 段关、叙述段开，开关要便宜。</li><li>正确性要求草稿与目标条件分布同源；表示不一致先吃掉接受率再谈加速。</li><li>声学码本不可投机、语义单元可投机、ASR 文本输出照常，语音管线分段适用。</li><li>出处：据 Leviathan et al. 与 Chen et al., 2023；EAGLE（Li et al., 2024）；Medusa（Cai et al., 2024）与语音 tokenizer 文献整理。</li></ul>',6))])}const c=n(m,[["render",d]]);export{f as __pageData,c as default};
